CREATE TABLE IF NOT EXISTS probes (
    id TEXT PRIMARY KEY NOT NULL,
    max_x INTEGER NOT NULL CHECK (max_x BETWEEN 0 AND 100),
    max_y INTEGER NOT NULL CHECK (max_y BETWEEN 0 AND 100),
    x INTEGER NOT NULL CHECK (x BETWEEN 0 AND max_x),
    y INTEGER NOT NULL CHECK (y BETWEEN 0 AND max_y),
    direction TEXT NOT NULL CHECK (direction IN ('NORTH', 'EAST', 'SOUTH', 'WEST'))
) STRICT;
